insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000001',(select id from skills where code='DSA-ARRAY'),'After the code: int x = 10; int *p = &x; *p = 20; what is the value of x?','[{"id": "A", "text": "10"}, {"id": "B", "text": "Compilation error"}, {"id": "C", "text": "The address of x"}, {"id": "D", "text": "20"}]'::jsonb,'D',1);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000002',(select id from skills where code='DSA-ARRAY'),'What is the time complexity of accessing the element arr[i] of an array?','[{"id": "A", "text": "O(1)"}, {"id": "B", "text": "O(n\u00b2)"}, {"id": "C", "text": "O(n)"}, {"id": "D", "text": "O(log n)"}]'::jsonb,'A',1);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000002',(select id from skills where code='DSA-ARRAY'),'What is the worst-case complexity of inserting an element at the beginning of a sequential array of n elements (shifting the others)?','[{"id": "A", "text": "O(1)"}, {"id": "B", "text": "O(n log n)"}, {"id": "C", "text": "O(log n)"}, {"id": "D", "text": "O(n)"}]'::jsonb,'D',2);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000002',(select id from skills where code='DSA-ARRAY'),'Given int a[5]; int *p = a; the expression *(p + 2) is equivalent to?','[{"id": "A", "text": "&a[2]"}, {"id": "B", "text": "a[2]"}, {"id": "C", "text": "a[3]"}, {"id": "D", "text": "a + 2"}]'::jsonb,'B',3);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000002',(select id from skills where code='DSA-ARRAY'),'An array allocated with int *a = new int[n]; must be freed how?','[{"id": "A", "text": "a = NULL;"}, {"id": "B", "text": "delete[] a;"}, {"id": "C", "text": "delete a;"}, {"id": "D", "text": "free(a);"}]'::jsonb,'B',4);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000003',(select id from skills where code='DSA-COMPLEXITY'),'A piece of code has two nested for loops, each running from 1 to n, with a simple assignment as the body. What is its complexity?','[{"id": "A", "text": "O(n\u00b2)"}, {"id": "B", "text": "O(n)"}, {"id": "C", "text": "O(2n)"}, {"id": "D", "text": "O(log n)"}]'::jsonb,'A',1);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000004',(select id from skills where code='DSA-LINKEDLIST'),'What is the complexity of inserting a node at the head of a singly linked list (with a head pointer)?','[{"id": "A", "text": "O(n)"}, {"id": "B", "text": "O(n\u00b2)"}, {"id": "C", "text": "O(1)"}, {"id": "D", "text": "O(log n)"}]'::jsonb,'C',1);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000004',(select id from skills where code='DSA-LINKEDLIST'),'What is the worst-case complexity of searching for a value in a singly linked list of n nodes?','[{"id": "A", "text": "O(n)"}, {"id": "B", "text": "O(1)"}, {"id": "C", "text": "O(n log n)"}, {"id": "D", "text": "O(log n)"}]'::jsonb,'A',2);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000004',(select id from skills where code='DSA-LINKEDLIST'),'To delete the node right after node p (where p->next is not NULL), the correct approach is?','[{"id": "A", "text": "Save q = p->next; set p->next = q->next; free q"}, {"id": "B", "text": "Set p->next = NULL"}, {"id": "C", "text": "Set p = p->next, then free p"}, {"id": "D", "text": "Free p->next first, then set p->next = p->next->next"}]'::jsonb,'A',3);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000004',(select id from skills where code='DSA-LINKEDLIST'),'Compared with arrays, the main drawback of linked lists is?','[{"id": "A", "text": "Elements cannot be deleted"}, {"id": "B", "text": "New elements cannot be added"}, {"id": "C", "text": "The size must be fixed"}, {"id": "D", "text": "Accessing the i-th element takes O(n)"}]'::jsonb,'D',4);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000005',(select id from skills where code='DSA-LINKEDLIST'),'The advantage of a doubly linked list over a singly linked list is?','[{"id": "A", "text": "It uses less memory"}, {"id": "B", "text": "It can be traversed in both directions, and a node can be deleted in O(1) when a pointer to it is known"}, {"id": "C", "text": "The i-th element is accessed in O(1)"}, {"id": "D", "text": "No head pointer is needed"}]'::jsonb,'B',1);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000005',(select id from skills where code='DSA-LINKEDLIST'),'In a singly circular linked list, where does the next pointer of the last node point?','[{"id": "A", "text": "The node just before it"}, {"id": "B", "text": "Itself"}, {"id": "C", "text": "NULL"}, {"id": "D", "text": "The first node"}]'::jsonb,'D',2);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000006',(select id from skills where code='DSA-STACK'),'Which principle does a stack follow?','[{"id": "A", "text": "FIFO (first in, first out)"}, {"id": "B", "text": "Random"}, {"id": "C", "text": "LIFO (last in, first out)"}, {"id": "D", "text": "By priority"}]'::jsonb,'C',1);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000006',(select id from skills where code='DSA-STACK'),'Which data structure is best suited to check whether a string of brackets ()[]{} is balanced?','[{"id": "A", "text": "Two-dimensional array"}, {"id": "B", "text": "Hash table"}, {"id": "C", "text": "Stack"}, {"id": "D", "text": "Queue"}]'::jsonb,'C',2);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000006',(select id from skills where code='DSA-STACK'),'What is the value of the postfix expression 3 4 + 2 * ?','[{"id": "A", "text": "24"}, {"id": "B", "text": "14"}, {"id": "C", "text": "9"}, {"id": "D", "text": "10"}]'::jsonb,'B',3);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000006',(select id from skills where code='DSA-STACK'),'Performing pop on an empty stack causes which situation?','[{"id": "A", "text": "Memory leak"}, {"id": "B", "text": "Stack underflow"}, {"id": "C", "text": "Collision"}, {"id": "D", "text": "Stack overflow"}]'::jsonb,'B',4);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000007',(select id from skills where code='DSA-QUEUE'),'Which principle does a queue follow?','[{"id": "A", "text": "By largest value"}, {"id": "B", "text": "FIFO (first in, first out)"}, {"id": "C", "text": "LIFO (last in, first out)"}, {"id": "D", "text": "Random"}]'::jsonb,'B',1);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000007',(select id from skills where code='DSA-QUEUE'),'Enqueue 1, 2, 3 into an empty queue, then dequeue once. Which element is at the front now?','[{"id": "A", "text": "The queue is empty"}, {"id": "B", "text": "1"}, {"id": "C", "text": "3"}, {"id": "D", "text": "2"}]'::jsonb,'D',2);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000007',(select id from skills where code='DSA-QUEUE'),'What is the main purpose of a circular queue implemented with an array?','[{"id": "A", "text": "To grow the array automatically"}, {"id": "B", "text": "To reuse the empty slots at the start of the array without shifting elements"}, {"id": "C", "text": "To allow random access"}, {"id": "D", "text": "To sort elements automatically"}]'::jsonb,'B',3);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000008',(select id from skills where code='DSA-RECURSION'),'A recursive factorial function missing its base case (n = 0 or n = 1) will lead to?','[{"id": "A", "text": "It runs faster"}, {"id": "B", "text": "The result is always 1"}, {"id": "C", "text": "The result is always 0"}, {"id": "D", "text": "Infinite recursion and a call stack overflow"}]'::jsonb,'D',1);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000009',(select id from skills where code='DSA-SORT'),'What is the worst-case complexity of Quick Sort?','[{"id": "A", "text": "O(n)"}, {"id": "B", "text": "O(n log n)"}, {"id": "C", "text": "O(n\u00b2)"}, {"id": "D", "text": "O(log n)"}]'::jsonb,'C',1);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000009',(select id from skills where code='DSA-SORT'),'What is the time complexity of Merge Sort in all cases?','[{"id": "A", "text": "O(n)"}, {"id": "B", "text": "O(n\u00b2)"}, {"id": "C", "text": "O(log n)"}, {"id": "D", "text": "O(n log n)"}]'::jsonb,'D',2);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000010',(select id from skills where code='DSA-TREE'),'In what order does a preorder traversal of a binary tree visit the nodes?','[{"id": "A", "text": "Right, root, left"}, {"id": "B", "text": "Left, root, right"}, {"id": "C", "text": "Left, right, root"}, {"id": "D", "text": "Root, left, right"}]'::jsonb,'D',1);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000010',(select id from skills where code='DSA-TREE'),'With the root at level 0, what is the maximum number of nodes at level i of a binary tree?','[{"id": "A", "text": "2^(i+1)"}, {"id": "B", "text": "2i"}, {"id": "C", "text": "2^i"}, {"id": "D", "text": "i\u00b2"}]'::jsonb,'C',2);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000010',(select id from skills where code='DSA-TREE'),'What sequence of keys does an inorder traversal of a binary search tree produce?','[{"id": "A", "text": "Ascending"}, {"id": "B", "text": "Level by level"}, {"id": "C", "text": "Random"}, {"id": "D", "text": "Descending"}]'::jsonb,'A',3);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000011',(select id from skills where code='DSA-TREE'),'Insert 50, 30, 70, 20, 40 in that order into an empty BST. What is the preorder traversal?','[{"id": "A", "text": "50 30 70 20 40"}, {"id": "B", "text": "20 40 30 70 50"}, {"id": "C", "text": "20 30 40 50 70"}, {"id": "D", "text": "50 30 20 40 70"}]'::jsonb,'D',1);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000011',(select id from skills where code='DSA-TREE'),'If keys already sorted in ascending order are inserted into an empty BST, what is the search complexity afterwards?','[{"id": "A", "text": "O(n log n)"}, {"id": "B", "text": "O(n)"}, {"id": "C", "text": "O(log n)"}, {"id": "D", "text": "O(1)"}]'::jsonb,'B',2);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000012',(select id from skills where code='DSA-TREE'),'What is the balance condition of an AVL tree?','[{"id": "A", "text": "The left subtree is always taller than the right"}, {"id": "B", "text": "All leaf nodes are at the same level"}, {"id": "C", "text": "For every node, the heights of its two subtrees differ by at most 1"}, {"id": "D", "text": "Both subtrees have the same number of nodes"}]'::jsonb,'C',1);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000012',(select id from skills where code='DSA-TREE'),'Insert 10, 20, 30 in that order into an empty AVL tree. Which rotation is needed and what is the new root?','[{"id": "A", "text": "Right rotation at node 30; the root is 10"}, {"id": "B", "text": "No rotation; the root stays 10"}, {"id": "C", "text": "Left-right rotation; the root is 30"}, {"id": "D", "text": "Left rotation at node 10; the root is 20"}]'::jsonb,'D',2);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000012',(select id from skills where code='DSA-TREE'),'What is the height of an AVL tree with n nodes?','[{"id": "A", "text": "O(log n)"}, {"id": "B", "text": "O(\u221an)"}, {"id": "C", "text": "O(n)"}, {"id": "D", "text": "O(1)"}]'::jsonb,'A',3);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000013',(select id from skills where code='DSA-HEAP'),'In a max-heap, what is the relationship between a parent node and its children?','[{"id": "A", "text": "Nodes at the same level are equal"}, {"id": "B", "text": "The parent is smaller than its children"}, {"id": "C", "text": "The parent''s value is greater than or equal to its children''s values"}, {"id": "D", "text": "The left child is always larger than the right"}]'::jsonb,'C',1);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000013',(select id from skills where code='DSA-HEAP'),'A heap is stored in an array indexed from 0. At which position is the left child of the node with index i?','[{"id": "A", "text": "2i + 2"}, {"id": "B", "text": "2i + 1"}, {"id": "C", "text": "i / 2"}, {"id": "D", "text": "2i"}]'::jsonb,'B',2);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000014',(select id from skills where code='DSA-GRAPH'),'Which data structure does breadth-first search (BFS) use?','[{"id": "A", "text": "Heap"}, {"id": "B", "text": "Hash table"}, {"id": "C", "text": "Stack"}, {"id": "D", "text": "Queue"}]'::jsonb,'D',1);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000014',(select id from skills where code='DSA-GRAPH'),'Which structure or technique is commonly used for depth-first search (DFS)?','[{"id": "A", "text": "Stack or recursion"}, {"id": "B", "text": "Queue"}, {"id": "C", "text": "Heap"}, {"id": "D", "text": "AVL tree"}]'::jsonb,'A',2);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000014',(select id from skills where code='DSA-GRAPH'),'How much memory does an adjacency matrix of a graph with n vertices take?','[{"id": "A", "text": "O(1)"}, {"id": "B", "text": "O(n)"}, {"id": "C", "text": "O(n\u00b2)"}, {"id": "D", "text": "O(n log n)"}]'::jsonb,'C',3);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000014',(select id from skills where code='DSA-GRAPH'),'A complete undirected graph (every pair of vertices is connected) has 5 vertices. How many edges does it have?','[{"id": "A", "text": "5"}, {"id": "B", "text": "10"}, {"id": "C", "text": "15"}, {"id": "D", "text": "20"}]'::jsonb,'B',4);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000014',(select id from skills where code='DSA-GRAPH'),'When is an adjacency list usually better than an adjacency matrix?','[{"id": "A", "text": "When the graph is sparse (few edges)"}, {"id": "B", "text": "When the number of vertices is very small"}, {"id": "C", "text": "When the graph is complete"}, {"id": "D", "text": "When edge lookup must be O(1) for every pair"}]'::jsonb,'A',5);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000015',(select id from skills where code='DSA-HASH'),'What is a collision in a hash table?','[{"id": "A", "text": "The hash function returns a negative value"}, {"id": "B", "text": "Two different keys are hashed to the same position"}, {"id": "C", "text": "One key is hashed to two positions"}, {"id": "D", "text": "The hash table is completely full"}]'::jsonb,'B',1);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000015',(select id from skills where code='DSA-HASH'),'How does collision handling by chaining work?','[{"id": "A", "text": "Find the next empty slot in the table"}, {"id": "B", "text": "Each slot of the table holds a linked list of elements with the same hash index"}, {"id": "C", "text": "Immediately double the table size"}, {"id": "D", "text": "Delete the old element"}]'::jsonb,'B',2);
insert into questions(quiz_id,skill_id,prompt,options,correct_answer,position) values ('bbbbbbbb-bbbb-4bbb-8bbb-000000000015',(select id from skills where code='DSA-HASH'),'With a good hash function and a reasonable load factor, what is the average search complexity in a hash table?','[{"id": "A", "text": "O(n log n)"}, {"id": "B", "text": "O(1)"}, {"id": "C", "text": "O(log n)"}, {"id": "D", "text": "O(n)"}]'::jsonb,'B',3);